function setView(name){const previous=enemyScope(state.singleMode,state.raidCount);rememberEnemy(previous);if(name==='single'||name==='formation')state.singleMode=name==='single';const scope=enemyScope(state.singleMode,state.raidCount);if(scope!==previous)restoreEnemy(scope);renderPresets();const view=name==='single'?'formation':name;for(const n of ['formation','results'])$('view-'+n).hidden=n!==view;for(const button of document.querySelectorAll('[data-view]')){const active=button.dataset.view===(view==='formation'&&state.singleMode?'single':view);button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}history.replaceState(null,'','#'+name);renderBoard();window.scrollTo(0,0);}
