function burstDetails(result){const rows=result.burst_timeline||[],patterns=result.burst_patterns||{};let cycle=1;const rendered=[];for(const row of rows){if(row.event==='full_burst 종료'){cycle++;continue;}if(row.character)rendered.push(`<tr><td>${cycle}</td><td>${Number(row.time).toFixed(2)}秒</td><td>${e(label(row.character))}</td><td>${e(row.event.replace('stage:','B').replace('reenter:','再突入 B').replace(' 사용',' 発動'))}</td></tr>`);}return `<details class="burst-details"><summary>バースト運用・実際の発動履歴を見る</summary><p class="subtle">${result.requested_burst_policy==='mast3'&&result.burst_policy==='auto'?'マスト不在：3の倍数指定は未適用。':''}${e(policyLabel(result.burst_policy||'auto'))}。周期指定は優先順位です。他の候補が使えない場合、指定外の周期でも発動します。配置や周期の最適解を探索した結果ではありません。</p><ul>${Object.entries(patterns).map(([n,p])=>`<li>${e(label(n))}：${e(Array.isArray(p)?p.join(' / '):p==='every:3'?'3の倍数':p==='every:1'?'毎回':p)}</li>`).join('')||'<li>周期指定なし（配置順・クールタイムで判定）</li>'}</ul><div class="table-scroll"><table><thead><tr><th>周期</th><th>時刻</th><th>キャラ</th><th>発動</th></tr></thead><tbody>${rendered.join('')||'<tr><td colspan="4">この計算時間内に発動はありません。</td></tr>'}</tbody></table></div></details>`;}
