function renderPresets(){const selected=$('enemy-preset').value,scope=enemyScope(state.singleMode,state.raidCount);$('preset-scope-label').textContent=({solo:'ソロレイド',union:'ユニオンレイド',single:'1部隊計算'}[scope])+'の敵プリセット';$('enemy-preset').replaceChildren(option('','カスタム条件'),...presetList().map(p=>option(p.id,p.label)));if(presetList().some(p=>p.id===selected))$('enemy-preset').value=selected;showPresetMembers(presetList().find(p=>p.id===$('enemy-preset').value));}
