function accelerationHTML(job){
 const c=job.combatAcceleration,a=job.acceleration;
 let text=c?c.backend==='cuda'?`GPU戦闘概算：${fmt(c.candidates)}候補 / ${e(c.device)} / カーネル ${c.kernel_ms}ms / 転送・実行 ${c.transfer_compute_ms}ms / 準備・初期化を含む全体 ${c.elapsed_ms}ms。射撃・リロード・バースト・対応効果を60fpsで計算しました。`:`GPU戦闘概算を利用できず、CPUで候補を計算しています：${e(c.reason||'')}`:'GPU選択時は、最大800候補をGPU上の戦闘モデルで概算し、候補を絞ります。';
 text+=' 推薦ダメージは上部「詳細計算」で選んだ方式で計算します。GPU詳細の未対応編成はCPUへ切り替え、各結果に実行方式を表示します。GPU概算は特殊挙動を省略するため、有力候補を落とす可能性があります。';
 const v=c?.validation;if(v?.samples)text+=` 詳細計算との比較 ${v.samples}候補：概算の平均相対誤差 ${(v.mean_absolute_relative_error*100).toFixed(1)}% / 最大 ${(v.max_absolute_relative_error*100).toFixed(1)}%。これは残した候補だけの比較です。`;
 const issues=c?.issues||[];
 const details=issues.length?`<details><summary>GPU概算の未対応・近似 ${issues.length}件（詳細計算では既存エンジンの対応範囲を適用）</summary><ul>${issues.map(x=>`<li>${e(label(x.character))} / ${e(x.effect)}：${e(x.reason)}</li>`).join('')}</ul></details>`:'';
 const selection=a?`<p class="subtle">最終部隊の組合せ：${a.backend==='cuda'?'GPU / CUDA':'CPU'}。全組合せの最適解は保証しません。</p>`:'';
 return `<p class="subtle">${text}</p>${details}${selection}`;
}
guarded(async()=>{const hardware=await api('/api/hardware'),gpu=$('selection-backend').querySelector('[value="cuda"]');$('detail-backend').querySelector('[value="metal_detail"]').disabled=!hardware.metal?.available;$('detail-backend').querySelector('[value="cuda_shared_detail"]').disabled=!hardware.shared_cuda?.available;gpu.disabled=!hardware.available;for(const v of ['cuda_detail','cuda_verified']){const opt=$('detail-backend').querySelector(`[value="${v}"]`);opt.disabled=!hardware.available;opt.textContent=v==='cuda_detail'?'GPU詳細（対応編成）':'GPU詳細＋CPU照合';}$('detail-backend').value=hardware.available?'cuda_verified':'cpu';gpu.textContent=hardware.available?'GPUで概算 → 選択した方式で詳細':'GPUを使用できません';$('selection-backend').value=hardware.available?'cuda':'cpu';$('gpu-status').textContent=hardware.available?`${hardware.device}：戦闘カーネルの実行確認済み。探索の概算で絞った候補は、上部「詳細計算」で選んだ方式で評価します。GPU詳細では対応編成の自動バースト・チャージ・特殊効果もGPUで処理し、未対応編成は理由を表示してCPUへ切り替えます。概算で除いた候補の順位は保証できません。`:hardware.metal?.available?'Metal詳細＋CPU照合を選択できます。対応条件は実蓄積・自動操作です。未対応条件は理由を表示してCPUへ切り替えます。':hardware.shared_cuda?.available?'共通CUDA詳細＋CPU照合を選択できます。計算時にGPU実行とCPU一致を確認し、未対応条件はCPUへ切り替えます。':`GPUを使用できません：${hardware.reason}。CPUで計算できます。`;if(hardware.available&&hardware.shared_cuda?.available)$('gpu-status').textContent+=' 共通CUDA詳細＋CPU照合も選択できます。';})();
$('open-blabla').onclick=guarded(()=>{let url;try{url=new URL($('blabla-url').value);}catch{throw Error('BlaBlaLinkのプロフィールURLを貼り付けてください。');}if(url.protocol!=='https:'||!['www.blablalink.com','blablalink.com'].includes(url.hostname)||!url.searchParams.has('openid'))throw Error('openidを含むBlaBlaLinkのプロフィールURLを指定してください。');window.open(url.href,'_blank','noopener,noreferrer');});
const importNonce=new URL(location.href).searchParams.get('blablalink_import');
if(importNonce&&/^[a-zA-Z0-9-]{20,80}$/.test(importNonce)&&window.opener){
  let importing=false;
  window.addEventListener('message',guarded(async event=>{
    if(!['https://www.blablalink.com','https://blablalink.com'].includes(event.origin)||event.source!==window.opener||event.data?.nonce!==importNonce)return;
    if(event.data.type==='nikke-tools-ping'){event.source.postMessage({type:'nikke-tools-ready',nonce:importNonce},event.origin);return;}
    if(event.data.type==='nikke-tools-import-error'){notice('BlaBlaLink：'+String(event.data.message||'読込に失敗しました。'));return;}
    if(event.data.type!=='nikke-tools-import'||importing)return;
    requireEditable();importing=true;
    try{const raw=event.data.payload;if(raw?.format!=='nikke-tools-blablalink-v1')throw Error('非対応のBlaBlaLinkデータです。');const imported=await api('/api/import',raw);setImport(imported);event.source.postMessage({type:'nikke-tools-imported',nonce:importNonce},event.origin);history.replaceState(null,'',location.pathname+'#formation');}
    catch(error){importing=false;notice(error.message);}
  }));
  notice('BlaBlaLinkのプロフィールからの読み込みを待っています。');
}

